function openById(sid,id){const s=sys(sid);if(id==='system-new'||id==='system')return createSystem(sid);if(id==='help'){let a=openApp(sid,'editor',{title:'操作指南 · 快速参考'});w(a).instance.filename='/Documents/操作指南.txt';w(a).instance.text='正在载入操作指南…';loadEditor(w(a));return;}if(id==='player')return openApp(sid,'player',{newInstance:true});openApp(sid,id);}
