function action(el){const act=el.dataset.action,wid=el.dataset.windowId,a=w(wid),s=a?sys(a.systemId):sys(el.dataset.systemId||'outer'),i=a?.instance||{};switch(act){case 'refresh':render();break;case 'new-system':case 'system-new':createSystem(s.id);menu=null;break;case 'settings':openApp(s.id,'settings');break;case 'help':openById(s.id,'help');break;case 'notifications':openApp(s.id,'widgets');break;case 'toggle-dnd':s.settings.dnd=!s.settings.dnd;notify(s.id,`免打扰${s.settings.dnd?'已开启':'已关闭'}`);render();break;case 'file-up':i.path=i.path.split('/').slice(0,-1).join('/')||'/';i.selectedPath=null;loadFiles(a);break;case 'file-copy':copyFile(a);break;case 'file-paste':pasteFile(a);break;case 'file-delete':deleteFile(a);break;case 'file-restore':restoreFile(a);break;case 'file-new':case 'newfile':{const name=prompt('新文件名称','新建文档.txt');if(name){i.items=i.items||[];i.items.push({name,path:i.path+'/'+name,kind:'text'});notify(s.id,`已创建 ${name}`);render();}break;}case 'newfolder':{const name=prompt('新文件夹名称','新建文件夹');if(name){i.items.push({name,dir:true,path:i.path+'/'+name});render();}break;}case 'browser-go':{let addr=document.querySelector(`[data-testid="browser-address"][data-window-id="${wid}"]`).value;navBrowser(a,addr);break;}case 'browser-back':browserCommand(a,'goBack');break;case 'browser-forward':browserCommand(a,'goForward');break;case 'browser-reload':browserCommand(a,'reload');break;case 'player-play':i.playing=true;render();break;case 'player-pause':i.playing=false;render();break;case 'player-stop':i.playing=false;i.position=0;if(i.controlProcessId){const p=s.processes.find(x=>x.id===i.controlProcessId);if(p)p.state='ended';i.controlProcessId=null;}i.rehearsal=false;drawScenes();render();break;case 'player-step':i.playing=false;i.position=Math.min(i.duration,i.position+1/30);drawScenes();render();break;case 'loop':i.loop=!i.loop;render();break;case 'camera':i.camera=i.camera==='跟随'?'自由':'跟随';render();break;case 'rehearsal':startFlightControl(a);break;case 'controller':openEditorFile(s.id,'/Programs/flight-control.nos');break;case 'save-flight':saveFlight(a);break;case 'project':project(a);break;case 'chart-connect':i.connected=true;i.sourceTitle='sample.sheet';publishWorkbook('outer');notify(s.id,'实时数据已送入图表进程的消息队列');render();break;case 'chart-disconnect':i.connected=false;notify(s.id,'已断开数据连接，保留最近数据');render();break;case 'chart-type':i.type=i.type==='line'?'bar':'line';render();break;case 'budget-save':s.budget=Number(document.querySelector(`[data-testid="tasks-budget"][data-window-id="${wid}"]`).value)||s.budget;render();notify(s.id,'预算配置已更新');break;case 'memory-save':s.mem=Math.max(1,Number(document.querySelector(`[data-testid="tasks-memory"][data-window-id="${wid}"]`).value)||s.mem);saveState();render();notify(s.id,'内存配额已更新');break;case 'storage-save':s.storage=Math.max(1,Number(document.querySelector(`[data-testid="tasks-storage"][data-window-id="${wid}"]`).value)||s.storage);saveState();render();notify(s.id,'存储配额已更新');break;case 'grant-save':{let target=el.closest('.app-window').querySelector('[data-testid="tasks-grant"]');if(target?.dataset.targetSystemId)sys(target.dataset.targetSystemId).grant=Math.max(0,Number(target.value)||250);render();break;}case 'system-toggle':{let x=sys(el.dataset.targetSystemId);x.state=x.state==='paused'?'running':'paused';notify(s.id,`${x.name} ${x.state==='paused'?'已暂停':'已继续'}`);render();break;}case 'system-step':{const x=sys(el.dataset.targetSystemId);if(x.state==='paused'){tick(x.id,true);notify(s.id,'子系统单步推进 16ms');}render();break;}case 'process-control':{const p=s.processes.find(x=>x.id===el.dataset.targetProcessId);if(p){if(el.dataset.processCommand==='suspend'){p.state='suspended';if(p.role==='kernel')s.state='paused';}else if(el.dataset.processCommand==='resume'&&p.state==='suspended'){p.state='ready';if(p.role==='kernel')s.state='running';}else if(el.dataset.processCommand==='end'){p.state='ended';if(p.role==='kernel'){s.state='error';s.kernelError='内核进程已结束';}}notify(s.id,`${p.name} ${p.state==='suspended'?'已挂起':p.state==='ready'?'已继续':'已结束'}`);saveState();render();}break;}case 'tick':tick(s.id,s.state==='paused');render();break;case 'snapshot':{const children=Object.values(systems).filter(x=>x.parentId===s.id);if(!children.length){notify(s.id,'此系统没有可快照的子系统');break;}let target=children[0];if(children.length>1){const ans=prompt('选择要快照的直属子系统：\n'+children.map((x,n)=>`${n+1}. ${x.name} (${x.id})`).join('\n'),'1');if(!ans)break;target=children[Number(ans)-1];}if(target)snapshot(target.id);break;}case 'restore-snapshot':restoreSnapshot(s.id);break;case 'fork':forkSystem(s.id);break;case 'kernel-open':openKernelSource(el.dataset.targetSystemId||s.id);break;case 'run-program':runProgram(a);break;case 'sheet-new':s.cells={A1:'项目',B1:'数量'};s.workbook='/Demo/untitled.sheet';a.dirty=true;render();break;case 'widget-timer-start':i.timerRunning=true;render();break;case 'widget-timer-pause':i.timerRunning=false;render();break;case 'widget-timer-reset':i.timerRunning=false;i.timer=300;render();break;case 'widget-note-save':notify(s.id,'便笺已保存在本系统');saveState();break;case 'toggle-menu':break;}}
function navBrowser(a,url){if(!/^https?:\/\//i.test(url))url='https://'+url;let t=a.instance.tabs.find(x=>x.id===a.instance.active);if(t){t.url=url;t.load='loading';t.title=url;}render();}
function browserCommand(a,cmd){const el=document.querySelector(`webview[data-window-id="${a.id}"]`);try{if(el?.[cmd]&&el[cmd+'Enabled']())el[cmd]();}catch{}}
function project(source){let ancestors=[];let p=sys(source.systemId).parentId;while(p){ancestors.push(p);p=sys(p).parentId;}if(!ancestors.length){notify(source.systemId,'根系统应用没有祖先桌面');return;}let target=ancestors[0];if(ancestors.length>1){let choice=prompt('投送目标祖先：\n'+ancestors.map((x,n)=>`${n+1}. ${sys(x).name} (${x})`).join('\n'),'1');if(choice)target=ancestors[Math.max(0,(+choice)-1)]||target;}if(source.instance.projected&&w(source.instance.projected)){let old=w(source.instance.projected);old.state='normal';old.z=++z;focus=old.id;render();return;}let id='w-'+uid(),pwin={id,systemId:target,appId:'projection',title:`${source.title} · 来自 ${source.systemId}`,state:'normal',x:100,y:60,width:600,height:430,z:++z,instance:{sourceWindowId:source.id,sourceSystemId:source.systemId,sourceAppId:source.appId}};wins[id]=pwin;sys(target).windows.push(id);source.instance.projected=id;source.instance.projectionFrames=0;ensureProjectionProcess(source);focus=id;render();notify(source.systemId,`已投送到 ${target}`);}
function openEditorFile(sid,path){const id=openApp(sid,'editor',{newInstance:true,title:path.split('/').pop()+' · 编辑器'}),a=w(id);a.instance.filename=path;a.instance.text='';render();loadEditor(a);}
async function openKernelSource(targetId){let child=sys(targetId);if(!child.parentId&&targetId==='outer')child=Object.values(systems).find(x=>x.parentId==='outer');if(!child?.parentId){notify(targetId,'此系统没有子系统内核源文件');return;}const file=child.kernelPath||`/Kernel/${child.id}.kernel.nos`;try{await window.host.readFile(child.parentId,file);}catch{await window.host.writeFile(child.parentId,file,'kernel v1\npolicy = round_robin\nquantum = 12\nmemory = 256\nstorage = 1024\nsyscall display.submit scene.copy message.send file.read');child.kernelPath=file;}openEditorFile(child.parentId,file);}
function programProcess(id,name,source,role='program',appId=null){const code=compile(source);return {id,name,appId,role,state:'ready',work:0,remaining:code.length,source,code,pc:0,vars:{},output:[],inbox:[]};}
async function bootSystem(id){const s=sys(id);try{const source=await window.host.readFile(s.parentId,s.kernelPath);if(!source.includes('kernel v')||source.includes('syntax_error'))throw Error('内核源文件无效');s.kernelSource=source;s.kernelQuantum=Math.max(1,Math.min(64,Number(source.match(/quantum\s*=\s*(\d+)/)?.[1]||12)));s.kernelPolicy=source.match(/policy\s*=\s*([\w-]+)/)?.[1]||'round_robin';s.schedulerCursor=0;s.processes=[programProcess(`kernel-${id}`,'kernel.nos',source,'kernel')];s.processes[0].memory=16;s.messages??=[];await loadWindowManager(s);s.state='running';saveState();render();}catch(e){s.state='error';s.kernelError=e.message;notify(s.parentId,`${id} 内核错误：${e.message}`);render();}}
async function loadWindowManager(s){try{const source=await window.host.readFile(s.id,'Programs/window-manager.nos');s.windowPolicy={focus:source.match(/^focus\s*=\s*(\w+)/m)?.[1]||'click',zOrder:source.match(/^z-order\s*=\s*([\w-]+)/m)?.[1]||'focused-last',hitTest:source.match(/^hit-test\s*=\s*([\w-]+)/m)?.[1]||'visible-only'};s.processes??=[];if(!s.processes.some(p=>p.role==='window-manager')){const p=programProcess(`wm-${s.id}`,'window-manager.nos',source,'window-manager');p.memory=12;s.processes.push(p);}}catch(e){s.state='error';s.kernelError=`窗口管理程序：${e.message}`;}}
function ensureAppProcess(sid,app,winId){const s=sys(sid);if(sid==='outer'||!['files','editor','tasks','player','charts'].includes(app))return;const pid=`app-${winId}`;let p=s.processes?.find(x=>x.id===pid);if(p){w(winId).instance.processId=pid;p.windowId=winId;return;}s.processes??=[];p={id:pid,name:`${app}.nos`,appId:app,role:'application',windowId:winId,state:'waiting',work:0,remaining:0,memory:8,code:[],pc:0,vars:{},output:[],inbox:[]};s.processes.push(p);w(winId).instance.processId=pid;window.host.readFile(sid,`Programs/${app}.nos`).then(source=>{p.source=source;p.code=compile(source);p.remaining=p.code.length;p.pc=0;p.state='ready';}).catch(e=>{p.state='error';p.error=e.message;});}
async function publishWorkbook(sourceSystemId){const source=sys(sourceSystemId);if(!source.cells){try{const sheet=JSON.parse(await window.host.readFile(sourceSystemId,source.workbook||'/Demo/sample.sheet'));source.cells=sheet.cells||{};}catch{source.cells={};}}for(const chart of Object.values(wins)){if(chart.appId!=='charts'||!chart.instance.connected)continue;const target=sys(chart.systemId);target.messages??=[];target.messages=target.messages.filter(m=>!(m.kind==='chart-data'&&m.to===chart.instance.processId));target.messages.push({to:chart.instance.processId,kind:'chart-data',windowId:chart.id,sourceSystemId,workbook:source.workbook||'/Demo/sample.sheet',version:source.version||1,data:JSON.parse(JSON.stringify(source.cells||{}))});}}
function ensureProjectionProcess(source){const system=sys(source.systemId),id=`projection-${source.id}`;if(system.processes?.some(p=>p.id===id))return;system.processes??=[];const p={id,name:'projection.nos',appId:'projection',role:'projection',windowId:source.id,state:'waiting',work:0,remaining:0,memory:6,code:[],pc:0,vars:{},output:[],inbox:[]};system.processes.push(p);window.host.readFile(source.systemId,'Programs/projection.nos').then(code=>{p.source=code;p.code=compile(code);p.remaining=p.code.length;p.state='ready';drawScenes();}).catch(e=>{p.state='error';p.error=e.message;});}
async function startFlightControl(a){if(!a)return;const s=sys(a.systemId),i=a.instance;for(const p of s.processes||[])if(p.role==='flight-control'&&p.state!=='ended')p.state='ended';i.rehearsal=true;i.position=0;i.playing=true;i.controlProcessId=null;i.targetHeading=Number(i.targetHeading||i.heading||90);i.heading=i.targetHeading;render();try{const source=await window.host.readFile(s.id,'Programs/flight-control.nos'),p=programProcess(`flight-${uid()}`,'flight-control.nos',source,'flight-control');p.windowId=a.id;p.appId='flight-control';p.memory=12;p.vars.targetHeading=i.targetHeading;p.vars.faultTime=Number(i.fault)||10;s.processes.push(p);i.controlProcessId=p.id;notify(s.id,'flight-control.nos 已载入并运行，开始排演');saveState();render();}catch(e){i.playing=false;notify(s.id,`飞控程序载入失败：${e.message}`);render();}}
async function saveFlight(a){const s=sys(a.systemId),i=a.instance,name=`flight-${Date.now()}.record.json`,record={scene:i.scene||'/Demo/helicopter-24.scene',position:i.position,wind:i.wind,targetHeading:i.targetHeading||i.heading,fault:i.fault,source:'/Programs/flight-control.nos'};try{await window.host.writeFile(s.id,`/Documents/${name}`,JSON.stringify(record,null,2));notify(s.id,`排演记录已保存到 /Documents/${name}`);saveState();}catch(e){notify(s.id,`排演记录保存失败：${e.message}`);}}
async function restartSystem(id){const target=sys(id);if(!target.parentId)return;function resetTree(s){s.state='running';s.virtualTime=0;s.processes=[];s.messages=[];s.used=0;s.budgetAvailable=0;s.cells=null;s.workbook='';s.kernelError=null;for(const wid of [...s.windows]){const a=w(wid);if(a&&a.appId!=='system')a.state='closed';}for(const c of Object.values(systems))if(c.parentId===s.id)resetTree(c);}resetTree(target);async function bootTree(s){await bootSystem(s.id);if(s.state==='running')for(const c of Object.values(systems).filter(x=>x.parentId===s.id))await bootTree(c);}await bootTree(target);notify(target.parentId,target.state==='running'?`${target.id} 已重新载入内核与窗口管理程序`:`${target.id} 重启失败：${target.kernelError}`);render();saveState();}
function compile(text){let lines=text.split(/\r?\n/).map(x=>x.replace(/\/\/.*$/,'').trim()).filter(Boolean),code=[];function block(start,end){for(let j=start;j<end;j++){let line=lines[j];let rep=line.match(/^repeat\s+(\d+)\s*\{/);let loop=line.match(/^while\s+true\s*\{/);if(rep||loop){let depth=1,k=j+1;for(;k<end&&depth;k++){if(lines[k].includes('{'))depth++;if(lines[k].includes('}'))depth--;}const to=k-1;if(loop){const at=code.length;code.push(...block(j+1,to),{op:'jump',to:at});}else{let body=block(j+1,to),n=Math.min(10000,+rep[1]);for(let q=0;q<n;q++)code.push(...body);}j=to;continue;}if(line==='}')continue;const p=line.match(/^print\s+(.+)$/);if(p)code.push({op:'print',expr:p[1]});else if(/^send\s+/.test(line)){const m=line.match(/^send\s+(?:process:)?([^\s]+)\s+["'](.+)["']$/);if(m)code.push({op:'send',to:m[1],value:m[2]});}else if(line==='receive')code.push({op:'receive'});else if(line.startsWith('syscall('))code.push({op:'syscall',expr:line});else if(/^(let\s+)?[A-Za-z_$][\w$]*\s*=/.test(line)){const m=line.match(/^(?:let\s+)?([\w$]+)\s*=\s*(.+)$/);code.push({op:'set',name:m[1],expr:m[2]});}}return code;}return block(0,lines.length);}
function value(expr,p){let x=expr.replace(/\b([A-Za-z_$][\w$]*)\b/g,(m,k)=>Object.hasOwn(p.vars,k)?String(p.vars[k]):m);if(!/^[\d\s.+*/()\-]+$/.test(x))return expr.replace(/^['"]|['"]$/g,'');return Function(`"use strict";return (${x})`)();}
function runInstruction(p,s){if(!p.code||p.pc>=p.code.length)return false;try{const op=p.code[p.pc++];if(op.op==='set')p.vars[op.name]=value(op.expr,p);else if(op.op==='print'){p.output??=[];p.output.push(String(value(op.expr,p)));}else if(op.op==='send'){const target=s.processes.find(x=>x.id===op.to||x.name===op.to);if(target){s.messages??=[];s.messages.push({from:p.id,to:target.id,value:op.value});}else p.output?.push(`未找到进程 ${op.to}`);}else if(op.op==='receive'){if(p.inbox?.length){p.vars.message=p.inbox.shift().value;}else{p.pc--;p.state='waiting';return false;}}else if(op.op==='jump')p.pc=op.to;else if(op.op==='syscall')runSystemCall(p,s,op.expr);return true;}catch(e){p.state='error';p.error=e.message;return false;}}
function runProgram(a){const text=document.querySelector(`[data-testid="editor-text"][data-window-id="${a.id}"]`)?.value||a.instance.text||'';a.instance.text=text;const code=compile(text),p={id:'p-'+uid(),name:a.instance.filename.split('/').pop(),state:'ready',work:0,remaining:code.length,source:text,code,pc:0,vars:{},output:[],inbox:[]};sys(a.systemId).processes.push(p);notify(a.systemId,`程序进程 ${p.name} 已进入轮转就绪队列`);saveState();}
// UI events are delegated so nested desktops share one consistent input path.
appRoot.addEventListener('click',e=>{const target=e.target.closest('[data-testid],[data-action],[data-app-id],[data-tab-id]');if(!target)return;const wid=target.dataset.windowId;if(target.dataset.testid==='window-close'){closeWindow(wid);return;}if(target.dataset.testid==='window-minimize'){let a=w(wid);a.state='minimized';render();return;}if(target.dataset.testid==='window-maximize'){let a=w(wid);a.state=a.state==='maximized'?'normal':'maximized';a.z=++z;focus=wid;render();return;}if(target.dataset.testid==='taskbar-item'){let a=w(wid);if(a){a.state=a.state==='minimized'?'normal':a.state;focusWindow(wid);render();}return;}if(target.dataset.testid==='start-toggle'){let id=target.dataset.systemId;menu=menu===id?null:id;ctx=null;render();return;}if(target.dataset.testid==='notifications-toggle'){openApp(target.dataset.systemId,'widgets');return;}if(target.dataset.testid==='system-new'){createSystem(target.dataset.systemId||w(wid)?.systemId||'outer');menu=null;render();return;}if(target.dataset.appId){openById(target.dataset.systemId,target.dataset.appId);menu=null;return;}if(target.dataset.tabId){let a=w(wid);if(target.dataset.testid==='browser-close-tab'){a.instance.tabs=a.instance.tabs.filter(x=>x.id!==target.dataset.tabId);if(!a.instance.tabs.length)a.instance.tabs=[{id:'tab'+Date.now(),url:'https://www.bilibili.com',title:'新标签页'}];a.instance.active=a.instance.tabs[0].id;}else a.instance.active=target.dataset.tabId;render();return;}if(target.dataset.action){action(target);return;}if(target.closest('.app-window'))focusWindow(target.closest('.app-window').dataset.windowId);});
appRoot.addEventListener('click',e=>{const t=e.target.closest('[data-testid="system-restart"]');if(!t)return;e.stopImmediatePropagation();restartSystem(t.dataset.targetSystemId);},true);
appRoot.addEventListener('dblclick',e=>{const icon=e.target.closest('[data-testid="desktop-icon"]');if(icon){if(icon.dataset.appId)openById(icon.dataset.systemId,icon.dataset.appId);else if(icon.dataset.filePath?.endsWith('.scene'))launchScene(icon.dataset.systemId,icon.dataset.filePath);return;}const bar=e.target.closest('.titlebar');if(bar){let a=w(bar.dataset.windowId);a.state=a.state==='maximized'?'normal':'maximized';render();}});
appRoot.addEventListener('contextmenu',e=>{const desk=e.target.closest('.system');if(!desk||e.target.closest('.app-window,.taskbar,.start-menu'))return;e.preventDefault();const r=desk.getBoundingClientRect();ctx={systemId:desk.dataset.systemId,x:e.clientX-r.left,y:e.clientY-r.top};menu=null;render();});
appRoot.addEventListener('input',e=>{const el=e.target,a=w(el.dataset.windowId);if(el.dataset.testid==='browser-address')return;if(el.dataset.testid==='editor-text'&&a){a.instance.text=el.value;a.dirty=true;const badge=a.querySelector?.('.title-text');return;}if(el.dataset.testid==='settings-scale'&&a){sys(a.systemId).settings.scale=+el.value;document.documentElement.style.zoom=(+el.value)+'%';}if(el.dataset.testid==='rehearsal-wind'&&a){a.instance.wind=+el.value;drawScenes();}if(el.dataset.testid==='sheet-cell'&&a){a.instance.pendingCell=el.dataset.cellAddress;a.instance.pendingValue=el.value;}});
appRoot.addEventListener('change',e=>{const el=e.target,a=w(el.dataset.windowId);if(el.dataset.testid==='settings-accent'&&a){sys(a.systemId).settings.accent=el.value;document.documentElement.style.setProperty('--accent',el.value);saveState();}if(el.dataset.testid==='settings-wallpaper'&&a){sys(a.systemId).settings.wallpaper=el.value;let desk=el.closest('.system');let wp=desk?.querySelector('.wallpaper');if(wp)wp.style.backgroundImage=el.value==='deep'?'linear-gradient(#111,#091424)':el.value==='aurora'?'linear-gradient(120deg,#153d52,#54375e,#d09376)':'url(\'fixtures/Wallpapers/alpine.svg\')';}if(el.dataset.testid==='settings-scale'&&a){sys(a.systemId).settings.scale=+el.value;render();}if(el.dataset.testid==='editor-filename'&&a){a.instance.filename=el.value;}if(el.dataset.testid==='editor-text'&&a){a.instance.text=el.value;a.dirty=true;}if(el.dataset.testid==='sheet-cell'&&a){const s=sys(a.systemId),address=el.dataset.cellAddress;s.cells[address]=el.value;a.instance.selected=address;a.dirty=true;s.version=(s.version||1)+1;clip=[el.value,...clip].slice(0,10);publishWorkbook(s.id);render();}if(el.dataset.testid==='sheet-formula'&&a){s=sys(a.systemId);if(a.instance.selected){s.cells[a.instance.selected]=el.value;a.dirty=true;s.version=(s.version||1)+1;publishWorkbook(s.id);}render();}if(el.dataset.testid==='sheet-save'&&a){a.dirty=false;notify(a.systemId,'工作簿已保存');render();}if(el.dataset.testid==='sheet-filename'&&a)sys(a.systemId).workbook=el.value;if(el.dataset.testid==='widget-note-text'&&a)a.instance.note=el.value;if(el.dataset.testid==='widget-timer-input'&&a)a.instance.timer=+el.value;if(el.dataset.testid==='player-seek'&&a){a.instance.position=+el.value;drawScenes();}if(el.dataset.testid==='player-time'&&a){a.instance.position=Math.max(0,Math.min(a.instance.duration,+el.value||0));drawScenes();}if(el.dataset.testid==='player-rate'&&a){a.instance.rate=+el.value;}if(el.dataset.testid==='chart-range'&&a)a.instance.range=el.value;if(el.dataset.testid==='chart-label-column'&&a)a.instance.label=el.value;if(el.dataset.testid==='chart-series'&&a)a.instance.series=el.value;if(el.dataset.testid==='chart-type'&&a){a.instance.type=el.value;render();}if(el.dataset.testid==='rehearsal-heading'&&a)a.instance.heading=+el.value;if(el.dataset.testid==='rehearsal-fault'&&a)a.instance.fault=+el.value;if(el.dataset.action==='system-name'&&a){sys(a.systemId).name=el.value;saveState();}});
appRoot.addEventListener('change',e=>{const el=e.target,a=w(el.dataset.windowId);if(!a)return;if(el.dataset.testid==='rehearsal-heading'){a.instance.targetHeading=+el.value;const p=sys(a.systemId).processes.find(x=>x.id===a.instance.controlProcessId);if(p)p.vars.targetHeading=+el.value;}if(el.dataset.testid==='rehearsal-fault'){const p=sys(a.systemId).processes.find(x=>x.id===a.instance.controlProcessId);if(p)p.vars.faultTime=+el.value;}if(el.dataset.testid==='files-path'){a.instance.path=el.value||'/';a.instance.selectedPath=null;loadFiles(a);}});
appRoot.addEventListener('click',async e=>{const t=e.target.closest('[data-testid]');if(!t)return;const a=w(t.dataset.windowId);if(t.dataset.testid==='files-new-file'&&a){e.stopImmediatePropagation();const name=prompt('新文件名称','新建文档.txt');if(name){await window.host.writeFile(a.systemId,joinPath(a.instance.path,name),'');await loadFiles(a);}return;}if(t.dataset.testid==='files-new-folder'&&a){e.stopImmediatePropagation();const name=prompt('新文件夹名称','新建文件夹');if(name){await window.host.makeDir(a.systemId,joinPath(a.instance.path,name));await loadFiles(a);}return;}if(t.dataset.testid==='files-paste'&&a){e.stopImmediatePropagation();await pasteFile(a);return;}if(t.dataset.testid==='files-nav'&&a){e.stopImmediatePropagation();a.instance.path=t.dataset.filePath;a.instance.selectedPath=null;await loadFiles(a);return;}if(t.dataset.testid==='sheet-save'&&a){e.stopImmediatePropagation();const s=sys(a.systemId),file=(document.querySelector(`[data-testid="sheet-filename"][data-window-id="${a.id}"]`)?.value||s.workbook||'/Demo/sample.sheet');try{await window.host.writeFile(s.id,file,JSON.stringify({name:file.split('/').pop(),cells:s.cells}));s.workbook=file;a.dirty=false;publishWorkbook(s.id);notify(s.id,'工作簿已保存到本系统文件');saveState();render();}catch(err){notify(s.id,`保存失败：${err.message}`);}return;}if(t.dataset.testid==='editor-save'&&a){e.stopImmediatePropagation();const filename=document.querySelector(`[data-testid="editor-filename"][data-window-id="${a.id}"]`).value,text=document.querySelector(`[data-testid="editor-text"][data-window-id="${a.id}"]`).value;try{await window.host.writeFile(a.systemId,filename,text);a.instance.filename=filename;a.instance.text=text;a.dirty=false;notify(a.systemId,`${filename} 已保存`);saveState();render();}catch(err){notify(a.systemId,`保存失败：${err.message}`);}return;}},true);
appRoot.addEventListener('click',e=>{const t=e.target.closest('[data-testid]');if(!t)return;const a=w(t.dataset.windowId);if(!a)return;const i=a.instance,s=sys(a.systemId);if(t.dataset.testid==='widget-timer-start'){i.timerRunning=true;render();}if(t.dataset.testid==='widget-timer-pause'){i.timerRunning=false;render();}if(t.dataset.testid==='widget-timer-reset'){i.timerRunning=false;i.timer=300;render();}if(t.dataset.testid==='widget-note-save'){i.note=appRoot.querySelector(`[data-testid="widget-note-text"][data-window-id="${a.id}"]`).value;notify(s.id,'便笺已保存');}if(t.dataset.testid==='sheet-save'){a.dirty=false;notify(s.id,'工作簿已保存');render();}if(t.dataset.testid==='editor-save'){i.filename=appRoot.querySelector(`[data-testid="editor-filename"][data-window-id="${a.id}"]`).value;i.text=appRoot.querySelector(`[data-testid="editor-text"][data-window-id="${a.id}"]`).value;a.dirty=false;notify(s.id,`${i.filename} 已保存`);render();}if(t.dataset.testid==='files-nav'){let file=appRoot.querySelector(`[data-testid="files-path"][data-window-id="${a.id}"]`);a.instance.path=t.dataset.filePath;render();}if(t.dataset.testid==='files-new-file')action({...t,dataset:{...t.dataset,action:'newfile'}});if(t.dataset.testid==='files-new-folder')action({...t,dataset:{...t.dataset,action:'newfolder'}});if(t.dataset.testid==='files-paste')notify(s.id,'已粘贴文件副本');});
appRoot.addEventListener('click',e=>{const item=e.target.closest('[data-testid="files-item"]');if(item){const a=w(item.dataset.windowId);if(a){a.instance.selectedPath=item.dataset.filePath;appRoot.querySelectorAll(`.file-item[data-window-id="${a.id}"]`).forEach(x=>x.classList.toggle('selected',x===item));}}});
appRoot.addEventListener('dblclick',e=>{const f=e.target.closest('[data-testid="files-item"]');if(!f)return;const a=w(f.dataset.windowId),file=(a.instance.items||[]).find(x=>x.path===f.dataset.filePath)||{path:f.dataset.filePath,name:f.dataset.filePath.split('/').pop(),dir:false};openFileItem(a.systemId,file);});
appRoot.addEventListener('dragstart',e=>{const file=e.target.closest('[data-testid="files-item"]');if(!file)return;const a=w(file.dataset.windowId),record=(a?.instance.items||[]).find(x=>x.path===file.dataset.filePath);if(!record)return;e.dataTransfer.setData('application/x-nested-file',JSON.stringify({sourceSystemId:a.systemId,path:record.path,name:record.name,dir:record.dir}));e.dataTransfer.effectAllowed='copy';});
appRoot.addEventListener('dragover',e=>{if(e.target.closest('[data-testid="files-list"]')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
appRoot.addEventListener('drop',async e=>{const list=e.target.closest('[data-testid="files-list"]');if(!list)return;e.preventDefault();const target=w(list.dataset.windowId),dest=target?.instance.path||'/',raw=e.dataTransfer.getData('application/x-nested-file');if(!target||!raw)return;try{const f=JSON.parse(raw);if(f.dir)throw Error('目前不能复制整个目录');const data=await window.host.readFile(f.sourceSystemId,f.path),to=joinPath(dest,f.name);await window.host.writeFile(target.systemId,to,data);notify(target.systemId,`已从 ${f.sourceSystemId} 复制 ${f.name}`);loadFiles(target);}catch(err){notify(target.systemId,`传递失败：${err.message}`);}});
appRoot.addEventListener('keydown',e=>{if(e.key==='Escape'){menu=null;ctx=null;render();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){let a=w(document.activeElement.dataset.windowId);if(a?.appId==='editor'){a.instance.text=document.activeElement.value;a.dirty=false;notify(a.systemId,'程序已保存');render();}if(a?.appId==='spreadsheet'){a.dirty=false;notify(a.systemId,'工作簿已保存');render();}}if(e.key==='Enter'&&e.target.dataset.testid==='browser-address'){let a=w(e.target.dataset.windowId);navBrowser(a,e.target.value);}if(e.key==='Enter'&&e.target.dataset.testid==='sheet-cell'){e.preventDefault();e.target.blur();}});
let drag=null;appRoot.addEventListener('pointerdown',e=>{const bar=e.target.closest('.titlebar'),grip=e.target.closest('.resize-grip');if(!bar&&!grip)return;const a=w((bar||grip).dataset.windowId);if(!a)return;focusWindow(a.id);drag={id:a.id,type:grip?'resize':'move',x:e.clientX,y:e.clientY,left:a.x,top:a.y,width:a.width,height:a.height};(bar||grip).setPointerCapture?.(e.pointerId);});window.addEventListener('pointermove',e=>{if(!drag)return;let a=w(drag.id);if(!a)return;if(drag.type==='move'&&a.state!=='maximized'){a.x=Math.max(0,drag.left+e.clientX-drag.x);a.y=Math.max(0,drag.top+e.clientY-drag.y);let el=appRoot.querySelector(`[data-window-id="${a.id}"].app-window`);if(el){el.style.left=a.x+'px';el.style.top=a.y+'px';}}else if(drag.type==='resize'){a.width=Math.max(330,drag.width+e.clientX-drag.x);a.height=Math.max(240,drag.height+e.clientY-drag.y);let el=appRoot.querySelector(`[data-window-id="${a.id}"].app-window`);if(el){el.style.width=a.width+'px';el.style.height=a.height+'px';}}});window.addEventListener('pointerup',()=>{if(drag){drawScenes();saveState();drag=null;}});
window.addEventListener('keydown',e=>{if(e.altKey&&e.key==='Tab'){e.preventDefault();let list=Object.values(wins).filter(x=>x.state!=='closed');if(list.length){let n=list.findIndex(x=>x.id===focus);focus=list[(n+1)%list.length].id;render();}}});
document.addEventListener('click',e=>{if(ctx&&!e.target.closest('.context-menu')){ctx=null;render();}else if(e.target.closest('.context-menu')){const b=e.target.closest('[data-action]');if(b){action(b);ctx=null;render();}}});
window.addEventListener('resize',drawScenes);
restore().then(()=>render());simTimer=setInterval(()=>{refreshData();},50);setInterval(saveState,5000);
